    terms: [["Attack surface", "Reachable interfaces, methods, users, and features available to an attacker."], ["Host key", "Server identity used by clients to detect unexpected server changes."], ["Public-key authentication", "User proves possession of a private key corresponding to an authorized public key."], ["Match block", "Conditional sshd policy."], ["authorized_keys option", "Per-key restriction such as source, forced command, or forwarding controls."], ["Privilege escalation", "Approved transition to a more privileged identity, commonly through sudo."]],
