    verify: "ssh -o BatchMode=yes -o ConnectTimeout=5 mgmt-host 'id; sudo -n true; echo sudo_status=$?'\nsudo sshd -t\nss -lntp | grep ':22'\nsudo journalctl -u ssh --since '-10 min' --no-pager", expected: ["Approved key login succeeds from management and denied methods/sources fail as intended.", "Effective config, listener, firewall, and log evidence all match the documented baseline."],
