    terms: [["Public key", "Shareable peer identity derived from a private key."], ["AllowedIPs", "Prefixes associated with a peer for outbound selection and inbound source validation."], ["Endpoint", "Peer's outer UDP address and port."], ["Handshake", "Authenticated key exchange establishing current session keys."], ["Persistent keepalive", "Optional periodic packet used to maintain NAT mappings."], ["Cryptokey routing", "Selection and validation of peers by keys plus inner prefixes."]],
