    verify: "sudo wg show wg0 latest-handshakes transfer endpoints allowed-ips\nip route get 10.20.0.10\nping -c 3 10.20.0.10\nsudo tcpdump -c 10 -nni underlay0 'udp port 51820'", expected: ["A fresh handshake and increasing transfer counters appear during the controlled inner test.", "The inner destination uses wg0 and the peer's AllowedIPs include the intended prefixes in both directions."],
