    terms: [["IKE", "Internet Key Exchange control protocol."], ["SA", "Security Association describing one direction of protected traffic."], ["SPI", "Security Parameters Index identifying an IPsec SA."], ["ESP", "Encapsulating Security Payload providing protected data transport."], ["XFRM", "Linux framework for IPsec policy and transformations."], ["Traffic selector", "Inner prefix/protocol/port scope protected by a child SA."], ["NAT-T", "ESP encapsulation over UDP/4500."]],
