    verify: "sudo swanctl --list-sas 2>/dev/null\nsudo ip -s xfrm policy\nsudo ip -s xfrm state\nip route get 10.20.0.10\nping -c 3 10.20.0.10", expected: ["IKE/child SA state and XFRM policy/state match the intended inner prefixes and outer endpoints.", "Outbound and inbound packet/byte counters increase during a successful test."],
