    terms: [["VXLAN", "Virtual Extensible LAN encapsulating Layer 2 over UDP/IP."], ["VNI", "24-bit VXLAN Network Identifier."], ["VTEP", "Endpoint performing VXLAN encapsulation."], ["BUM", "Broadcast, Unknown unicast, and Multicast traffic requiring replication/flood handling."], ["FDB", "Bridge/VXLAN mapping of inner MAC and remote location."], ["MACsec", "IEEE 802.1AE hop-by-hop Ethernet protection."]],
    nodes: ["LOCAL BRIDGE", "VTEP A", "IP UNDERLAY", "VTEP B", "REMOTE BRIDGE"], diagramCaption: "VXLAN extends a bridge over an IP underlay; MACsec, when used, protects individual Ethernet links rather than the whole overlay automatically.",
