    verify: "ip -details link show vxlan100\nbridge link show master br100\nbridge fdb show br br100\nip route get 192.0.2.20\nsudo tcpdump -c 10 -nnei underlay0 'udp port 4789'", expected: ["The VNI, local/remote VTEPs, destination port, MTU, bridge, and underlay route match design.", "Underlay capture shows UDP/VXLAN while overlay endpoints exchange the intended inner frames."],
    safety: ["VXLAN can extend broadcast domains and amplify loops/BUM traffic; test only in isolated namespaces or approved virtual networks."], mistakes: ["Assuming VXLAN encrypts traffic.", "Routing to the remote VTEP through the VXLAN overlay.", "Ignoring inner MTU and BUM/flood behavior."],
